def build_sa(s):
    n = len(s)
    sa = list(range(n))
    rank = [ord(c) for c in s]
    k = 1
    while True:
        key = [(rank[i], rank[i + k] if i + k < n else -1) for i in range(n)]
        sa.sort(key=key.__getitem__)
        new = [0] * n
        for t in range(1, n):
            new[sa[t]] = new[sa[t - 1]] + (key[sa[t - 1]] != key[sa[t]])
        rank = new
        if rank[sa[-1]] == n - 1:
            return sa
        k *= 2


def build_lcp(s, sa):
    n = len(s)
    rank = [0] * n
    for i, p in enumerate(sa):
        rank[p] = i
    lcp = [0] * max(n - 1, 0)
    h = 0
    for i in range(n):
        if rank[i] > 0:
            j = sa[rank[i] - 1]
            while i + h < n and j + h < n and s[i + h] == s[j + h]:
                h += 1
            lcp[rank[i] - 1] = h
            if h:
                h -= 1
        else:
            h = 0
    return lcp


def longestKTimes(s, k):
    from collections import deque
    n = len(s)
    if k > n:
        return 0
    sa = build_sa(s)
    lcp = build_lcp(s, sa)
    w = k - 1
    dq = deque()
    best = 0
    for i, v in enumerate(lcp):
        while dq and lcp[dq[-1]] >= v:
            dq.pop()
        dq.append(i)
        if dq[0] <= i - w:
            dq.popleft()
        if i >= w - 1:
            best = max(best, lcp[dq[0]])
    return best
